// LAMP AI — trusted sources only:
//   1. Coran  : texte uthmani + traduction Hamidullah (fichiers locaux, scripts/fetch-sources.mjs)
//   2. Hadiths: Bukhari, Muslim, Abu Dawud, Malik (Muwatta), 40 Nawawi — traduction française
//   3. Khassaids de Cheikh Ahmadou Bamba : 122 fichiers + 7 394 distiques indexés (versets_cache.jsonl)
// Nothing here is generated by the AI: every text returned is read from a file.
import fs from 'fs';
import path from 'path';
import readline from 'readline';
import { initializeApp } from 'firebase/app';
import { getFirestore, collection, getDocs, query, where } from 'firebase/firestore/lite';
import { ai, withTimeout } from './ai.js';
import { TEXTES_DIR, SOURCES_DIR, VERSETS_CACHE, MODELS, firebaseConfig } from './config.js';

// ─── text helpers ────────────────────────────────────────────────────────────
export function norm(s) {
  return String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');
}
// Phonetic key for Khassaid titles: "Mawahibou Nafih" ≈ "mawahibu", "Djazboul" ≈ "jazbul"
function titleKey(s) {
  return norm(s).replace(/ou/g, 'u').replace(/oo|uu/g, 'u').replace(/aa/g, 'a').replace(/ii|ee/g, 'i')
    .replace(/dj/g, 'j').replace(/kh/g, 'x').replace(/ch/g, 'sh').replace(/[^a-z]/g, '');
}
const STOP = new Set(('les des une pour dans avec sans mais donc comme quoi quel quelle quels quelles est sont ' +
  'etre avoir fait faire sur par plus tres tout tous toute leur leurs nous vous ils elles cette ces son ses que qui ' +
  'dont elle lui aux ont parle parler dit dire selon islam prophete allah dieu hadith coran verset').split(' '));
export function keywords(text) {
  return [...new Set(norm(text).split(/[^a-z]+/).filter((w) => w.length >= 4 && !STOP.has(w)))];
}
const stem = (w) => w.slice(0, Math.max(4, Math.min(6, w.length - 1)));

function scoreText(haystackNorm, kws) {
  let s = 0;
  for (const k of kws) if (haystackNorm.includes(stem(k))) s += k.length >= 6 ? 2 : 1;
  return s;
}

// ─── KHASSAIDS (files) ───────────────────────────────────────────────────────
const KHASSAIDS = new Map();   // file stem -> { title, file, verses: [[h1,h2],...] }

function loadKhassaidFiles() {
  if (!fs.existsSync(TEXTES_DIR)) { console.warn(`[Sources] Khassaid folder missing: ${TEXTES_DIR}`); return; }
  for (const f of fs.readdirSync(TEXTES_DIR).filter((x) => x.endsWith('.txt'))) {
    const lines = fs.readFileSync(path.join(TEXTES_DIR, f), 'utf8').split('\n').filter((l) => l.trim().length > 5);
    const verses = [];
    for (let i = 0; i + 1 < lines.length; i += 2) verses.push([lines[i].trim(), lines[i + 1].trim()]);
    const stemName = f.replace(/\.txt$/, '');
    const title = stemName.split('_').map((w) => w[0].toUpperCase() + w.slice(1)).join(' ');
    KHASSAIDS.set(stemName, { title, file: f, verses });
  }
  console.log(`[Sources] ${KHASSAIDS.size} Khassaids loaded from files`);
}

// Usual names people use → file stem
const ALIASES = {
  mawahibunafih: 'mawahibu', mawahibunafi: 'mawahibu', mawahibulnafih: 'mawahibu',
  jazbulqulub: 'jazbu', jazbulxulub: 'jazbu', jazbul: 'jazbu',
  matlabulfawzayn: 'matlabul_fawzayni', matlabfawzayni: 'matlabul_fawzayni',
  nurudarayni: 'nuuru_daarayni', nurudarayn: 'nuuru_daarayni', nurudarein: 'nuuru_daarayni',
  jalibatulmarxibi: 'jalibatul_maraghibi', jalibatul: 'jalibatul_maraghibi',
  mafatihulbishri: 'mafatihul_bishri', mafatihulbichri: 'mafatihul_bishri',
  mafatihuljinan: 'mafatihul_jinan', tawbatunasuh: 'tawbatun_nasuuh', tawbatunnasuh: 'tawbatun_nasuuh',
  wakanahaxan: 'wa_kaana_haqqan', wakanaxaxan: 'wa_kaana_haqqan', wakanahaqan: 'wa_kaana_haqqan',
  asmaulhusna: 'asma_ul_husna', munawarsudur: 'muqadamatul_amdah',
};

/** Finds the Khassaid named in a text. Returns the file stem or null. */
export function findKhassaid(text) {
  if (!text) return null;
  if (!KHASSAIDS.size) loadKhassaidFiles();
  const q = titleKey(text);
  if (!q) return null;
  // 1. full title contained in the text (longest first)
  const byLength = [...KHASSAIDS.keys()].sort((a, b) => titleKey(b).length - titleKey(a).length);
  for (const k of byLength) if (q.includes(titleKey(k))) return k;
  // 2. usual names
  for (const [alias, k] of Object.entries(ALIASES).sort((a, b) => b[0].length - a[0].length)) {
    if (q.includes(alias) && KHASSAIDS.has(k)) return k;
  }
  // 3. distinctive first word of a title ("Mawahibou" → mawahibu)
  const words = norm(text).split(/[^a-z]+/).map(titleKey).filter((w) => w.length >= 5);
  for (const k of byLength) {
    const first = titleKey(k.split('_')[0]);
    if (first.length < 5) continue;
    const shared = [...KHASSAIDS.keys()].filter((o) => titleKey(o.split('_')[0]) === first).length;
    if (shared === 1 && words.some((w) => w.startsWith(first) || first.startsWith(w))) return k;
  }
  return null;
}

export function khassaidInfo(stemName) {
  const k = KHASSAIDS.get(stemName);
  return k ? { titre: k.title, nombre_de_distiques: k.verses.length } : null;
}

/** Exact verses from the file. from/to are 1-based and inclusive. */
export function readKhassaid(nameOrText, from = 1, to = null) {
  if (!KHASSAIDS.size) loadKhassaidFiles();
  const stemName = KHASSAIDS.has(nameOrText) ? nameOrText : findKhassaid(nameOrText);
  if (!stemName) return { erreur: `Khassaid introuvable dans la bibliothèque : "${nameOrText}"` };
  const k = KHASSAIDS.get(stemName);
  const total = k.verses.length;
  const start = Math.max(1, Math.min(Number(from) || 1, total));
  const end = Math.max(start, Math.min(Number(to) || start + 9, total, start + 39));   // max 40 at once
  if (Number(from) > total) {
    return { titre: k.title, nombre_de_distiques: total, erreur: `Ce Khassaid n'a que ${total} distiques.` };
  }
  return {
    titre: k.title,
    nombre_de_distiques: total,
    distiques: k.verses.slice(start - 1, end).map(([a, b], i) => ({ numero: start + i, texte: `${a}\n${b}` })),
  };
}

export function listKhassaids() {
  if (!KHASSAIDS.size) loadKhassaidFiles();
  return [...KHASSAIDS.values()].map((k) => `${k.title} (${k.verses.length})`).join(', ');
}

// ─── KHASSAIDS (semantic index) ──────────────────────────────────────────────
let VERSETS = null;
let versetsLoading = null;

export function loadVersets() {
  if (VERSETS) return Promise.resolve(VERSETS);
  if (versetsLoading) return versetsLoading;
  versetsLoading = (async () => {
    const out = [];
    if (fs.existsSync(VERSETS_CACHE)) {
      const t = Date.now();
      const rl = readline.createInterface({ input: fs.createReadStream(VERSETS_CACHE), crlfDelay: Infinity });
      for await (const line of rl) {
        if (!line.trim()) continue;
        try {
          const v = JSON.parse(line);
          if (v.e?.length) out.push({ t: v.t, n: v.n, c: v.c, e: Float32Array.from(v.e) });
        } catch { /* skip broken line */ }
      }
      console.log(`[Sources] ${out.length} Khassaid distiques indexed in ${Date.now() - t}ms`);
    } else {
      console.warn(`[Sources] ${VERSETS_CACHE} missing — run scripts/cache_vectors.mjs (semantic search disabled)`);
    }
    VERSETS = out;
    return out;
  })();
  return versetsLoading;
}

function cosine(a, b) {
  let d = 0, na = 0, nb = 0;
  for (let i = 0; i < a.length; i++) { d += a[i] * b[i]; na += a[i] * a[i]; nb += b[i] * b[i]; }
  return na && nb ? d / Math.sqrt(na * nb) : 0;
}

async function embed(text) {
  const r = await withTimeout(ai.models.embedContent({ model: MODELS.embed, contents: String(text).slice(0, 2000) }), 20_000, 'embed');
  return r.embeddings?.[0]?.values || [];
}

/** Khassaid passages about a topic (meaning search, keyword fallback). */
export async function searchKhassaid(topic, limit = 6) {
  const versets = await loadVersets();
  if (!versets.length) return [];
  try {
    const q = await embed(topic);
    if (q.length) {
      return versets
        .map((v) => ({ v, s: cosine(q, v.e) }))
        .filter((x) => x.s > 0.5)
        .sort((a, b) => b.s - a.s)
        .slice(0, limit)
        .map(({ v }) => ({ khassaid: v.t, distique: v.n, texte: v.c.replace(/^\[[^\]]*\]\n?/, '') }));
    }
  } catch (e) {
    console.warn('[Sources] semantic search failed:', e.message);
  }
  const kws = keywords(topic);
  return versets.filter((v) => kws.some((k) => norm(v.t).includes(k))).slice(0, limit)
    .map((v) => ({ khassaid: v.t, distique: v.n, texte: v.c.replace(/^\[[^\]]*\]\n?/, '') }));
}

// ─── CORAN ───────────────────────────────────────────────────────────────────
let QURAN = null;   // [{ num, nom, nomFr, ayahs: [{ n, ar, fr, frNorm }] }]

function loadQuran() {
  if (QURAN) return QURAN;
  const ar = path.join(SOURCES_DIR, 'quran-uthmani.json');
  const fr = path.join(SOURCES_DIR, 'fr.hamidullah.json');
  if (!fs.existsSync(ar) || !fs.existsSync(fr)) {
    console.warn('[Sources] Quran files missing — run: node scripts/fetch-sources.mjs');
    QURAN = [];
    return QURAN;
  }
  const A = JSON.parse(fs.readFileSync(ar, 'utf8')).data.surahs;
  const F = JSON.parse(fs.readFileSync(fr, 'utf8')).data.surahs;
  QURAN = A.map((s, i) => ({
    num: s.number, nom: s.name, nomFr: s.englishName,
    ayahs: s.ayahs.map((a, j) => ({ n: a.numberInSurah, ar: a.text, fr: F[i].ayahs[j].text, frNorm: norm(F[i].ayahs[j].text) })),
  }));
  console.log(`[Sources] Coran loaded (${QURAN.length} sourates)`);
  return QURAN;
}

function findSurah(s) {
  const Q = loadQuran();
  const n = Number(s);
  if (n >= 1 && n <= 114) return Q[n - 1];
  const k = titleKey(s).replace(/^(al|an|ar|as|at|az|ad|ash|sourate|surat|surah)/, '');
  return Q.find((x) => titleKey(x.nomFr).replace(/^(al|an|ar|as|at|az|ad|ash)/, '') === k) || null;
}

export function readQuran(sourate, verset, jusqua = null) {
  const s = findSurah(sourate);
  if (!s) return { erreur: `Sourate introuvable : ${sourate}` };
  const from = Number(verset) || 1;
  if (from < 1 || from > s.ayahs.length) {
    return { sourate: `${s.num}. ${s.nomFr}`, erreur: `La sourate ${s.nomFr} compte ${s.ayahs.length} versets : le verset ${verset} n'existe pas.` };
  }
  const to = Math.min(Math.max(from, Number(jusqua) || from), from + 9, s.ayahs.length);
  return {
    sourate: `${s.num}. ${s.nomFr} (${s.nom})`,
    versets: s.ayahs.slice(from - 1, to).map((a) => ({ reference: `${s.num}:${a.n}`, arabe: a.ar, francais: a.fr })),
    traduction: 'Muhammad Hamidullah',
  };
}

export function searchQuran(mots, limit = 5) {
  const Q = loadQuran();
  const kws = keywords(mots);
  if (!kws.length || !Q.length) return [];
  const hits = [];
  for (const s of Q) for (const a of s.ayahs) {
    const sc = scoreText(a.frNorm, kws);
    if (sc >= Math.min(3, kws.length + 1)) hits.push({ sc, s, a });   // at least 2 strong keywords
  }
  return hits.sort((x, y) => y.sc - x.sc).slice(0, limit).map(({ s, a }) => ({
    reference: `${s.num}:${a.n}`, sourate: s.nomFr, arabe: a.ar, francais: a.fr,
  }));
}

// ─── HADITHS ─────────────────────────────────────────────────────────────────
export const HADITH_COLLECTIONS = {
  bukhari: 'Sahih al-Bukhari', muslim: 'Sahih Muslim', abudawud: 'Sunan Abu Dawud',
  malik: 'Muwatta Malik', nawawi: 'Les 40 hadiths de an-Nawawi',
};
let HADITHS = null;   // { key: [{ n, text, textNorm, grade }] }

function loadHadiths() {
  if (HADITHS) return HADITHS;
  HADITHS = {};
  for (const key of Object.keys(HADITH_COLLECTIONS)) {
    const f = path.join(SOURCES_DIR, `fra-${key}.json`);
    if (!fs.existsSync(f)) continue;
    const d = JSON.parse(fs.readFileSync(f, 'utf8'));
    HADITHS[key] = d.hadiths.filter((h) => h.text && h.text.trim()).map((h) => ({
      n: h.hadithnumber, text: h.text.trim(), textNorm: norm(h.text),
      grade: (h.grades || []).map((g) => `${g.grade} (${g.name})`).join(', '),
    }));
  }
  const n = Object.values(HADITHS).reduce((a, b) => a + b.length, 0);
  if (n) console.log(`[Sources] ${n} hadiths loaded (${Object.keys(HADITHS).join(', ')})`);
  else console.warn('[Sources] Hadith files missing — run: node scripts/fetch-sources.mjs');
  return HADITHS;
}

function collectionKey(c) {
  const k = titleKey(c || '');
  if (!k) return null;
  if (k.includes('buxari') || k.includes('bukhari') || k.includes('boukhari')) return 'bukhari';
  if (k.includes('muslim') || k.includes('moslim')) return 'muslim';
  if (k.includes('dawud') || k.includes('dawd') || k.includes('daud')) return 'abudawud';
  if (k.includes('malik') || k.includes('muwata')) return 'malik';
  if (k.includes('nawawi')) return 'nawawi';
  return null;
}

export function searchHadith(mots, recueil = null, limit = 4) {
  const H = loadHadiths();
  const kws = keywords(mots);
  if (!kws.length) return [];
  const only = collectionKey(recueil);
  const hits = [];
  for (const [key, list] of Object.entries(H)) {
    if (only && key !== only) continue;
    const bonus = key === 'bukhari' || key === 'muslim' ? 1 : 0;   // the two Sahih first
    for (const h of list) {
      const sc = scoreText(h.textNorm, kws);
      if (sc >= Math.min(2, kws.length)) hits.push({ sc: sc + bonus, key, h });
    }
  }
  return hits.sort((a, b) => b.sc - a.sc).slice(0, limit).map(({ key, h }) => ({
    recueil: HADITH_COLLECTIONS[key], numero: h.n, texte: h.text.length > 600 ? h.text.slice(0, 600) + '…' : h.text, ...(h.grade ? { authenticite: h.grade } : {}),
  }));
}

export function readHadith(recueil, numero) {
  const H = loadHadiths();
  const key = collectionKey(recueil);
  if (!key || !H[key]) return { erreur: `Recueil non disponible : ${recueil}. Disponibles : ${Object.values(HADITH_COLLECTIONS).join(', ')}` };
  const h = H[key].find((x) => x.n === Number(numero));
  if (!h) return { erreur: `Le hadith n°${numero} n'existe pas dans ${HADITH_COLLECTIONS[key]}.` };
  return { recueil: HADITH_COLLECTIONS[key], numero: h.n, texte: h.text, ...(h.grade ? { authenticite: h.grade } : {}) };
}

// ─── Firestore: Khassaid summaries + reviewed notes (cached) ─────────────────
const db = getFirestore(initializeApp(firebaseConfig));
const cache = { kb: null, kbAt: 0, notes: '', notesAt: 0 };
const TTL = 30 * 60_000;

async function knowledgeBase() {
  if (cache.kb && Date.now() - cache.kbAt < TTL) return cache.kb;
  try {
    const snap = await withTimeout(getDocs(collection(db, 'knowledge_base')), 15_000, 'firestore kb');
    cache.kb = snap.docs.map((d) => d.data());
    cache.kbAt = Date.now();
  } catch (e) {
    console.warn('[Sources] knowledge_base unavailable:', e.message);
    cache.kb = cache.kb || [];
  }
  return cache.kb;
}

/** Summary/themes of a Khassaid from the dashboard knowledge base, if any. */
export async function khassaidSummary(stemName) {
  const info = khassaidInfo(stemName);
  if (!info) return null;
  const kb = await knowledgeBase();
  const item = kb.find((x) => titleKey(x.title) === titleKey(info.titre));
  if (!item) return null;
  return {
    themes: item.themes || [],
    resume: item.frenchSummary || '',
    ...(item.sourceRef ? { reference: item.sourceRef } : {}),
  };
}

/**
 * Notes from the dashboard (ai_memory). Only spelling/terminology notes are used:
 * "fact" and "correction" notes were written automatically from chats and are NOT verified
 * (one claimed Mawahibu has 212 verses, the file has 166) — the library always wins.
 */
export async function reviewedNotes() {
  if (Date.now() - cache.notesAt < TTL) return cache.notes;
  try {
    const snap = await withTimeout(getDocs(query(collection(db, 'ai_memory'), where('status', '==', 'active'))), 15_000, 'firestore notes');
    cache.notes = snap.docs.map((d) => d.data())
      .filter((m) => m.type === 'terminology' && m.content && !/\d/.test(m.content))
      .map((m) => `- ${m.content}`).join('\n');
  } catch (e) {
    console.warn('[Sources] ai_memory unavailable:', e.message);
  }
  cache.notesAt = Date.now();
  return cache.notes;
}

export function warmUp() {
  loadKhassaidFiles();
  loadQuran();
  loadHadiths();
  loadVersets().catch(() => {});
  knowledgeBase().catch(() => {});
}
